import React, { useEffect, useState } from "react";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./result-list-page.css";
import { useNavigate } from "react-router-dom";

const ResultListPage: React.FC = () => {
  const [testData, setTestData] = useState({
    incomplete_tests: [],
    tests_with_pending_results: [],
    tests_with_results: [],
  });
  const [message, setMessage] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("incomplete");
  const navigate = useNavigate();

  useEffect(() => {
    let isMounted = true;
    const email = localStorage.getItem("userEmail");

    if (!email) {
      setMessage("Email not found. Please log in.");
      return;
    }

    const fetchTestData = async () => {
      try {
        // Step 1: Get Roll Number using Email
        const rollNoResponse = await fetch("http://localhost:5000/get_rollno", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email }),
        });

        if (!rollNoResponse.ok) {
          setMessage("Failed to retrieve roll number.");
          return;
        }

        const rollNoData = await rollNoResponse.json();
        const rollno = rollNoData.rollno;

        // Step 2: Fetch Test Data using Roll Number
        const response = await fetch("http://localhost:5000/resultlist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email }),
        });

        if (response.ok) {
          const data = await response.json();
          if (isMounted) {
            setTestData({
              incomplete_tests: data.incomplete_tests ?? [],
              tests_with_pending_results: data.tests_with_pending_results ?? [],
              tests_with_results: data.tests_with_results ?? [],
            });
          }
        } else {
          const error = await response.json();
          setMessage(error.error || "Failed to fetch test data.");
        }
      } catch (err: any) {
        setMessage(err.message || "Something went wrong.");
      }
    };

    fetchTestData();

    const interval = setInterval(fetchTestData, 5000);
    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, []);

  const renderTests = () => {
    let tests = [];
    let actionLabel = "";

    if (activeTab === "incomplete") {
      tests = testData.incomplete_tests;
      actionLabel = "Resume";
    } else if (activeTab === "pending") {
      tests = testData.tests_with_pending_results;
      actionLabel = "Check Result";
    } else {
      tests = testData.tests_with_results;
      actionLabel = "View Result";
    }

    return tests.length > 0 ? (
      tests.map((test) => (
        <div key={test.test_id} className="test-item">
          <span>Test ID: {test.test_id}</span>
          <span>Created At: {test.created_at}</span>
          <button onClick={() => navigate(`/view-result/${test.test_id}`)} className="action-button">
            {actionLabel}
          </button>
        </div>
      ))
    ) : (
      <p>No {activeTab} tests available.</p>
    );
  };

  return (
    <div className="App">
      <Header />
      <div className="result-container">
        <div className="main-content">
          <h2>Test Status</h2>
          {message && <p className="feedback-message">{message}</p>}

          <div className="tab-buttons">
            <button onClick={() => setActiveTab("incomplete")}>Incomplete Tests</button>
            <button onClick={() => setActiveTab("pending")}>Pending Tests</button>
            <button onClick={() => setActiveTab("results")}>Results</button>
          </div>

          <div className="test-list">{renderTests()}</div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ResultListPage;
